package com.mealmate.order;import jakarta.validation.*;import jakarta.validation.constraints.*;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/food-orders")class OrderController{final OrderService s;OrderController(OrderService x){s=x;}@PostMapping OrderModel create(@RequestHeader("Idempotency-Key")String k,@Valid @RequestBody CreateRequest q){return s.create(q,k);}@GetMapping("/{id}")OrderModel get(@PathVariable UUID id){return s.get(id);}@PostMapping("/{id}/cancel")OrderModel cancel(@PathVariable UUID id){return s.cancel(id);}}record CreateRequest(@NotNull UUID customerId,@NotNull UUID restaurantId,@NotEmpty List<Item>items,boolean failPayment,boolean failDeliveryAssignment){}record Item(@NotNull UUID menuItemId,@Min(1)int quantity){}
